dashboard.definition:
{
	"visualizations": {
		"viz_pZLsO3n7": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			}
		},
		"viz_RaSQZQg0": {
			"type": "splunk.line",
			"dataSources": {
				"primary": "ds_x5TFDlm9_ds_gxQTUbyK"
			},
			"title": "SAP RISE host event count",
			"options": {
				"backgroundColor": "transparent"
			}
		},
		"viz_TWx0q4MO": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			}
		},
		"viz_7NM08jn4": {
			"type": "splunk.linkgraph",
			"dataSources": {
				"primary": "ds_5anrJzix_ds_E237l4zD"
			},
			"showProgressBar": false,
			"showLastUpdated": false,
			"title": "Source to sourcetype mapping",
			"options": {
				"nodeWidth": 202,
				"nodeSpacingY": 21,
				"nodeSpacingX": 41,
				"showValueCounts": false,
				"nodeHeight": 23,
				"backgroundColor": "transparent",
				"nodeColor": "#0877a6"
			}
		},
		"viz_nraRnnPr": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			}
		},
		"viz_Rr0ozI8N": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			}
		},
		"viz_E6VoPgPK": {
			"type": "splunk.singlevalue",
			"title": "SAP RISE Active Hosts",
			"dataSources": {
				"primary": "ds_9q0Wbh4a_ds_FlqNQGID"
			},
			"options": {
				"majorValue": "> sparklineValues | lastPoint()",
				"trendValue": "> sparklineValues | delta(-2)",
				"sparklineValues": "> primary | seriesByName('count(host)')",
				"backgroundColor": "transparent"
			},
			"description": ""
		},
		"viz_YGJifJFJ": {
			"type": "splunk.table",
			"title": "SAP RISE host Latest Activity",
			"dataSources": {
				"primary": "ds_82WV7n8Q_ds_kbElziov"
			},
			"description": "",
			"options": {
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				},
				"headerVisibility": "fixed",
				"backgroundColor": "transparent"
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToDashboard",
					"options": {
						"app": "splunk_ta_sap_logserv",
						"dashboard": "sap_rise_host_details",
						"newTab": true,
						"tokens": [
							{
								"token": "host_name",
								"value": "row.Host.value"
							}
						]
					}
				}
			]
		}
	},
	"dataSources": {
		"ds_kbElziov": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_kzavdy7f",
				"query": "| dedup host\n| fields host, _time\n| stats count by host, _time\n| eval _time = now() - _time \n| sort + _time\n| eval elapsed_time = case(_time < 60, _time.\" seconds ago\",\n_time < 3600, round(_time/60).\" minutes ago\",\n_time < 86400, round(_time/3600).\" hours ago\",\ntrue(), round(_time/86400).\" days ago\")\n| table host, elapsed_time\n| rename host AS \"Host\", elapsed_time AS \"Latest Activity\""
			},
			"name": "host_latest_activity"
		},
		"ds_FlqNQGID": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_wl4Og2TU",
				"query": "| dedup host\n| fields host, _time\n| stats count by host, _time\n| eval _time = now() - _time \n| where _time <= (70*86400)\n| stats count(host)"
			},
			"name": "host_active_count"
		},
		"ds_wl4Og2TU": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` \n| fields source, sourcetype, host, _time\n",
				"queryParameters": {
					"earliest": "-30d@d",
					"latest": "now"
				}
			},
			"name": "search_base"
		},
		"ds_E237l4zD": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_kzavdy7f",
				"query": "| stats count by sourcetype source, host\n| fields - count"
			},
			"name": "host_source_sourcetype_map"
		},
		"ds_kzavdy7f": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_wl4Og2TU",
				"query": "| dedup host, source, sourcetype"
			},
			"name": "host_search_base"
		},
		"ds_gxQTUbyK": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_wl4Og2TU",
				"query": "|timechart span=1d limit=0 count by host"
			},
			"name": "events_by_host"
		},
		"ds_x5TFDlm9_ds_gxQTUbyK": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_wl4Og2TU",
				"query": "|timechart span=1d limit=0 count by host"
			},
			"name": "events_by_host copy 1"
		},
		"ds_5anrJzix_ds_E237l4zD": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_kzavdy7f",
				"query": "| stats count by sourcetype source, host\n| fields - count"
			},
			"name": "host_source_sourcetype_map copy 1"
		},
		"ds_9q0Wbh4a_ds_FlqNQGID": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_wl4Og2TU",
				"query": "| dedup host\n| fields host, _time\n| stats count by host, _time\n| eval _time = now() - _time \n| where _time <= (70*86400)\n| stats count(host)"
			},
			"name": "host_active_count copy 1"
		},
		"ds_82WV7n8Q_ds_kbElziov": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_kzavdy7f",
				"query": "| dedup host\n| fields host, _time\n| stats count by host, _time\n| eval _time = now() - _time \n| sort + _time\n| eval elapsed_time = case(_time < 60, _time.\" seconds ago\",\n_time < 3600, round(_time/60).\" minutes ago\",\n_time < 86400, round(_time/3600).\" hours ago\",\ntrue(), round(_time/86400).\" days ago\")\n| table host, elapsed_time\n| rename host AS \"Host\", elapsed_time AS \"Latest Activity\""
			},
			"name": "host_latest_activity copy 1"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					}
				}
			}
		}
	},
	"inputs": {},
	"description": "Data pipeline overview from last 30 days",
	"title": "SAP Logserv data pipeline Overview",
	"layout": {
